import java.lang.reflect.Constructor;
import java.lang.reflect.Modifier;
import java.util.List;

public class PizzaOrderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            PizzaOrder plain = PizzaOrder.builder("medium").build();
            check("plain medium size", "medium", plain.getSize());
            check("plain medium price", 10, plain.price());
            check("plain medium toppings", "[]", plain.getToppings().toString());

            PizzaOrder loaded = PizzaOrder.builder("small")
                    .topping("ham")
                    .topping("HAM")
                    .withExtraCheese()
                    .build();
            check("duplicate topping ignored", "[ham]", loaded.getToppings().toString());
            check("small with one topping and cheese", 13, loaded.price());
            check("extra cheese flag", true, loaded.hasExtraCheese());

            PizzaOrder max = PizzaOrder.builder("large")
                    .topping("a").topping("b").topping("c").topping("d").topping("e")
                    .topping(null).topping("")
                    .build();
            check("at most four toppings", "[a, b, c, d]", max.getToppings().toString());
            check("large with four toppings", 20, max.price());

            PizzaOrder odd = PizzaOrder.builder("jumbo").build();
            check("unknown size falls back to 10", 10, odd.price());

            List<String> handedOut = loaded.getToppings();
            handedOut.add("sneaky");
            check("returned topping list is a copy", "[ham]", loaded.getToppings().toString());

            boolean allPrivate = true;
            for (Constructor<?> c : PizzaOrder.class.getDeclaredConstructors()) {
                if (!Modifier.isPrivate(c.getModifiers())) {
                    allPrivate = false;
                }
            }
            check("every PizzaOrder constructor is private", true, allPrivate);
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

