import java.util.ArrayList;
import java.util.List;

public class PizzaOrder {

    private final String size;
    private final List<String> toppings;
    private final boolean extraCheese;

    private PizzaOrder(Builder builder) {
        this.size = builder.size();
        this.toppings = new ArrayList<>(builder.toppings());
        this.extraCheese = builder.extraCheese();
    }

    public static Builder builder(String size) {
        return new Builder(size);
    }

    public String getSize() {
        return size;
    }

    public boolean hasExtraCheese() {
        return extraCheese;
    }

    public List<String> getToppings() {
        return new ArrayList<>(toppings);
    }

    public int price() {
        int base;
        if ("small".equals(size)) {
            base = 8;
        } else if ("large".equals(size)) {
            base = 12;
        } else {
            base = 10;
        }
        int total = base + 2 * toppings.size();
        if (extraCheese) {
            total += 3;
        }
        return total;
    }

    public static class Builder {

        private final String size;
        private final List<String> toppings = new ArrayList<>();
        private boolean extraCheese = false;

        private Builder(String size) {
            this.size = size;
        }

        String size() {
            return size;
        }

        List<String> toppings() {
            return toppings;
        }

        boolean extraCheese() {
            return extraCheese;
        }

        public Builder topping(String name) {
            if (name == null || name.isEmpty()) {
                return this;
            }
            if (toppings.size() >= 4) {
                return this;
            }
            for (String existing : toppings) {
                if (existing.equalsIgnoreCase(name)) {
                    return this;
                }
            }
            toppings.add(name);
            return this;
        }

        public Builder withExtraCheese() {
            this.extraCheese = true;
            return this;
        }

        public PizzaOrder build() {
            return new PizzaOrder(this);
        }
    }
}
